using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Diten.FpaService.Application.Modules.ScenarioPlanning;
using Diten.FpaService.Domain.Modules.ScenarioPlanning;

namespace Diten.FpaService.ContractTests.Modules.ScenarioPlanning;

public sealed class ScenarioPlanningContractTests
{
    private static readonly string Root=FindRoot();private static readonly string Fixtures=Path.Combine(Root,"execution/domains/enterprise-strategy-business-performance/module-packs/fixtures/MOD-0138/audit");
    [Fact] public void Exact_16_permissions_and_worker_separation_are_closed()
    {var e=ScenarioPlanningAuthorizationManifest.Entries;Assert.Equal(16,e.Count);Assert.Equal(16,e.Select(x=>x.Permission).Distinct(StringComparer.Ordinal).Count());Assert.All(e,x=>Assert.Equal(x.OperationId,x.Permission));Assert.DoesNotContain(e,x=>x.Permission==ScenarioPlanningAuthorizationManifest.WorkerOperation);}
    [Fact] public void Reference_contracts_and_ppm_wrappers_are_minimal()
    {Assert.Equal(new[]{"ContractName","ContractVersion","ScenarioId","ScenarioVersionId","ScenarioVersionNumber"},typeof(ScenarioVersionReferenceV1).GetProperties().Select(x=>x.Name));Assert.Equal(new[]{"ContractName","ContractVersion","ComparatorRunId","ComparatorOutputId","OutputVersion"},typeof(ComparatorOutputReferenceV1).GetProperties().Select(x=>x.Name));foreach(var type in new[]{typeof(InvestmentCaseScenarioVersionReferenceV1),typeof(InvestmentCaseComparatorOutputReferenceV1),typeof(SelectedScenarioReferenceV1)}){var names=type.GetProperties().Select(x=>x.Name).ToArray();Assert.DoesNotContain(names,x=>x.Contains("Assumption")||x.Contains("Ranking")||x.Contains("OutputPayload")||x.Contains("Algorithm"));}}
    [Fact] public void Canonical_audit_payload_checksum_and_schema_are_exact()
    {var payload=File.ReadAllBytes(P("scenario-planning-audit-intent-submitted-v1.canonical.json"));Assert.Equal(247,payload.Length);var sha=Convert.ToHexString(SHA256.HashData(payload)).ToLowerInvariant();Assert.Equal("db9385def75d885a581554e10ce38877408ed445ed3c4f62e17283b30830462b",sha);Assert.Equal(sha+"\n",File.ReadAllText(P("scenario-planning-audit-intent-submitted-v1.canonical.sha256")));using var schema=JsonDocument.Parse(File.ReadAllBytes(P("scenario-planning-audit-intent-submitted-v1.schema.json")));Assert.Equal("MOD-0138",schema.RootElement.GetProperty("x-moduleCode").GetString());Assert.Equal(1,schema.RootElement.GetProperty("x-eventVersion").GetInt32());Assert.False(schema.RootElement.GetProperty("additionalProperties").GetBoolean());}
    [Fact] public void Scenario_only_test_hmac_recomputes_exactly()
    {using var vector=J("scenario-planning-audit-intent-submitted-v1.signing-vector.json");var root=vector.RootElement;var payload=File.ReadAllBytes(P("scenario-planning-audit-intent-submitted-v1.canonical.json"));var fields=new[]{root.GetProperty("signatureScheme").GetString(),root.GetProperty("eventId").GetString(),root.GetProperty("eventName").GetString(),root.GetProperty("eventVersion").GetInt32().ToString(),root.GetProperty("tenantId").GetString(),root.GetProperty("correlationId").GetString(),root.GetProperty("producer").GetString(),root.GetProperty("causationId").GetString(),root.GetProperty("occurredAtUtc").GetString(),payload.Length.ToString()};var header=Encoding.UTF8.GetBytes(string.Join('\n',fields)+"\n");var input=new byte[header.Length+payload.Length];header.CopyTo(input,0);payload.CopyTo(input,header.Length);Assert.Equal(root.GetProperty("signingInputSha256").GetString(),Convert.ToHexString(SHA256.HashData(input)).ToLowerInvariant());var key=Convert.FromBase64String(root.GetProperty("fixtureSecretBase64").GetString()!);var signature=Convert.ToHexString(HMACSHA256.HashData(key,input)).ToLowerInvariant();using var expected=J("scenario-planning-audit-intent-submitted-v1.expected-signature.json");Assert.Equal(expected.RootElement.GetProperty("signatureLowerHex").GetString(),signature);Assert.True(root.GetProperty("testOnly").GetBoolean());}
    [Fact] public void Allowlist_provenance_and_production_rejection_matrices_are_complete()
    {using var allow=J("scenario-planning-audit-intent-submitted-v1.allowlist-matrix.json");Assert.Equal(60,allow.RootElement.GetProperty("cartesianCaseCount").GetInt32());Assert.Equal(14,allow.RootElement.GetProperty("acceptedPairCount").GetInt32());Assert.Equal(46,allow.RootElement.GetProperty("rejectedCrossPairCount").GetInt32());using var neg=J("scenario-planning-audit-intent-submitted-v1.contract-negative-matrix.json");Assert.Equal(25,neg.RootElement.GetProperty("caseCount").GetInt32());using var delegated=J("scenario-planning-audit-intent-submitted-v1.delegated-provenance.negative.json");Assert.Equal(19,delegated.RootElement.GetProperty("caseCount").GetInt32());using var non=J("scenario-planning-audit-intent-submitted-v1.non-delegated-provenance.matrix.json");Assert.Equal(2,non.RootElement.GetProperty("caseCount").GetInt32());using var prod=J("scenario-planning-audit-intent-submitted-v1.production-validator.negative.json");Assert.Equal(5,prod.RootElement.GetProperty("caseCount").GetInt32());Assert.All(prod.RootElement.GetProperty("cases").EnumerateArray(),x=>{Assert.Equal("TerminalSecurityFailure",x.GetProperty("expectedDisposition").GetString());Assert.False(x.GetProperty("reasonIsInvalidHmac").GetBoolean());});}
    [Fact] public void Validation_modes_reject_coercion_and_current_mode_requires_selected_wrapper()
    {Assert.Throws<NotSupportedException>(()=>ScenarioPlanningValidators.ValidateNoVersionCoercion("2.0"));var scenario=new ScenarioVersionReferenceV1("fpa.scenario-planning-reference","1.0",Guid.NewGuid(),Guid.NewGuid(),1);Assert.Throws<ArgumentException>(()=>ScenarioPlanningValidators.Validate(new(Guid.NewGuid(),ReferenceValidationMode.CurrentSelectionEligibility,scenario,null)));}
    private static string P(string name)=>Path.Combine(Fixtures,name);private static JsonDocument J(string name)=>JsonDocument.Parse(File.ReadAllBytes(P(name)));
    private static string FindRoot(){var d=new DirectoryInfo(AppContext.BaseDirectory);while(d is not null&&!File.Exists(Path.Combine(d.FullName,"AGENTS.md")))d=d.Parent;return d?.FullName??throw new InvalidOperationException();}
}
